// год крупно над карточкой
const _cardDraw = T.card.draw;
T.card.draw = function (lt, P, t) {
  let s = _cardDraw.call(this, lt, P, t);
  if (P.year) { const p = pop(lt, .05, .45); s += `<g transform="translate(${W / 2},215) scale(${p})"><text font-size="110" font-weight="900" fill="${YEL}" stroke="${OL}" stroke-width="14" paint-order="stroke" text-anchor="middle" y="38">${esc(P.year)}</text></g>`; }
  return s;
};

const bC = (art, cap, lines, o = {}) => Object.assign({ type: 'card', art, cap, seq: lines.map(l => ['nb', l]) }, o);
const bY = (year, art, cap, lines, o = {}) => bC(art, cap, lines, Object.assign({ year, artScale: .82 }, o));
const bL = (title, items, intro, lines, o = {}) => Object.assign({ type: 'list', title, items, seq: [['nb', intro], ...lines.map(l => ['nb', l])] }, o);
const bH = (text, art, line, o = {}) => Object.assign({ type: 'hook', tag: 'История бренда', tagCol: '#ffa94d', text, art, seq: [['nb', line]], k: [[0, { eyes: 'wide', mouth: 'o' }]] }, o);
const bO = (ask, line) => ({ type: 'outro', ask, seq: [['nb', line], ['nb', 'Подписывайся — дальше будет *ещё больше* историй.']] });

